div.style:
background: #FFFFFF;
border: 0.75px solid #E5E7EB;
border-radius: 8px;
box-shadow: 0 1px 4px rgba(0,0,0,0.04);
border-left: 3px solid #2563EB;
padding: 16px 20px;
display: flex;
align-items: center;
justify-content: center;
min-height: 64px;
box-sizing: border-box;
height: 100%;

font-family: 'Inter', sans-serif;
font-weight: 500;
font-size: 11px;
color: #111827;
text-align: center;
line-height: 1.4;
max-width: 85%;
